    SPELL_DASH                = 2106617,
    SPELL_THRASH              = 3391,
    SPELL_OHGAN_FIERCE_BLOW   = 975011
};

class npc_ohgan : public CreatureScript
{
public:
    npc_ohgan() : CreatureScript("npc_ohgan") { }

    struct npc_ohganAI : public ScriptedAI
    {
        npc_ohganAI(Creature* creature) : ScriptedAI(creature), instance(creature->GetInstanceScript()) { }

        void Reset() override
        {
            _scheduler.CancelAll();
            _scheduler.SetValidator([this]
            {
                return !me->HasUnitState(UNIT_STATE_CASTING);
            });

            reviveGUID.Clear();
        }

        void JustEngagedWith(Unit* who) override
        {
            if (!who->IsPlayer())
                return;

            _scheduler.Schedule(9s, [this](TaskContext context)
            {
                DoCastVictim(SPELL_SHRED_ARMOR);
                context.Repeat(13s, 16s);
            });
            _scheduler.Schedule(0s, [this](TaskContext context)
            {
                DoCastSelf(SPELL_DASH);
                context.Repeat(20s);
            });
            _scheduler.Schedule(6600ms, [this](TaskContext context)
            {
                DoCastVictim(SPELL_OHGAN_FIERCE_BLOW);
                context.Repeat(7s, 16600ms);
            });
            _scheduler.Schedule(12s, 18s, [this](TaskContext context)
            {
                DoCastSelf(SPELL_THRASH);
                context.Repeat(12s, 18s);
            });
        }

        void KilledUnit(Unit* victim) override
        {
            if (!victim->IsPlayer())
                return;

            reviveGUID = victim->GetGUID();
            RevivePlayer(victim, reviveGUID);
        }

        void SetGUID(ObjectGuid const& guid, int32 /*type = 0 */) override
        {
            reviveGUID = guid;
        }

        void JustDied(Unit* /*killer*/) override
        {
            instance->SetBossState(DATA_OHGAN, DONE);
        }

        void UpdateAI(uint32 diff) override
        {
            _scheduler.Update(diff);

            if (!UpdateVictim())
            {
                return;
            }

            DoMeleeAttackIfReady();
        }

    private:
        InstanceScript* instance;
        ObjectGuid reviveGUID;
        TaskScheduler _scheduler;
    };

    CreatureAI* GetAI(Creature* creature) const override
    {
        return GetZulGurubAI<npc_ohganAI>(creature);
    }
