    SPELL_SPIDER_EGGS         = 24082,

    // All
    SPELL_SPIDER_FORM         = 24084,
    SPELL_TRANSFORM_BACK      = 24085,
    SPELL_THRASH              = 3391,
    SPELL_HATCH_SPIDER_EGG    = 24082,
    SPELL_HATCH_EGGS          = 24083,

    // Spawn of Mar'li
    SPELL_GROWTH              = 2118117,
    SPELL_FULL_GROWN          = 24088,
    SPELL_SPAWN_FIERCE_BLOW   = 975011
};

